function createAsset(THREE, seed, textures, params, addons) {
  params = params || {};
  const scale = params.scale ?? 1;
  const capColor = params.capColor ?? '#ad4e27';
  const undersideColor = params.undersideColor ?? '#ead7af';
  const stemColor = params.stemColor ?? '#ddc79d';
  const barkColor = params.barkColor ?? '#493127';
  const woodColor = params.woodColor ?? '#c79559';
  const mossColor = params.mossColor ?? '#567332';
  const logLength = params.logLength ?? 3.25;
  const logRadius = params.logRadius ?? 0.46;
  const matureCount = Math.max(0, Math.floor(params.matureCount ?? 5));
  const youngCount = Math.max(0, Math.floor(params.youngCount ?? 3));
  const stemHeight = params.stemHeight ?? 1;
  const capSize = params.capSize ?? 1;
  const mossCount = Math.max(0, Math.floor(params.mossCount ?? 32));
  const branchEnabled = params.branchEnabled ?? true;
  const lengthScale = logLength / 3.25;
  const radialScale = logRadius / 0.46;
  const logY = 0.49 * radialScale;
  const group = new THREE.Group();
  group.name = 'Woodland mushrooms on mossy log';
  let state = (Number(seed) || 1) >>> 0;
  const random = () => {
    state = (1664525 * state + 1013904223) >>> 0;
    return state / 4294967296;
  };
  const geometries = new Set(), materials = new Set(), instances = [];
  const geo = g => { geometries.add(g); return g; };
  function material(color, roughness = 0.95) {
    const m = new THREE.MeshStandardMaterial({ color, roughness, flatShading: true });
    materials.add(m);
    return m;
  }
  function mesh(g, m, x = 0, y = 0, z = 0) {
    const object = new THREE.Mesh(g, m);
    object.position.set(x, y, z);
    object.castShadow = true;
    object.receiveShadow = true;
    group.add(object);
    return object;
  }
  function paletteColor(input, reference, target) {
    const c = new THREE.Color(input);
    const a = new THREE.Color(reference), b = new THREE.Color(target);
    c.r = Math.min(1, c.r * b.r / a.r);
    c.g = Math.min(1, c.g * b.g / a.g);
    c.b = Math.min(1, c.b * b.b / a.b);
    return c;
  }
  const bark = [material(barkColor), material(paletteColor(barkColor, '#493127', '#624032')), material(paletteColor(barkColor, '#493127', '#77513a'))];
  const wood = material(woodColor);
  const ringMat = material(paletteColor(woodColor, '#c79559', '#916039'));
  ringMat.side = THREE.DoubleSide;
  const cream = material(undersideColor);
  const stemMat = material(stemColor);
  const mossMat = material(mossColor);
  const capMat = material(capColor);
  capMat.vertexColors = true;

  const core = mesh(geo(new THREE.CylinderGeometry(0.44 * radialScale, logRadius, logLength, 14)), bark[0], 0, logY, 0);
  core.rotation.z = Math.PI / 2;

  // Overlapping long bark scales wrap the solid timber core.
  for (let i = 0; i < 15; i++) {
    const angle = i / 15 * Math.PI * 2;
    const pieces = i % 3 === 0 ? 3 : 2;
    for (let j = 0; j < pieces; j++) {
      const start = -logLength / 2 + j * logLength / pieces - (j ? 0.035 * lengthScale : 0);
      const end = Math.min(logLength / 2, start + logLength / pieces + 0.065 * lengthScale);
      const points = [];
      for (let k = 0; k < 3; k++) {
        const x = start + (end - start) * k / 2;
        for (const side of [-1, 1]) {
          const a = angle + side * 0.23;
          const outer = (0.48 + random() * 0.045) * radialScale;
          points.push(new THREE.Vector3(x, logY + Math.cos(a) * outer, Math.sin(a) * outer));
          points.push(new THREE.Vector3(x, logY + Math.cos(a) * 0.425 * radialScale, Math.sin(a) * 0.425 * radialScale));
        }
      }
      mesh(geo(new addons.ConvexGeometry(points)), bark[(i + j) % bark.length]);
    }
  }

  // Cut end grain with irregular concentric growth bands.
  for (const sign of [-1, 1]) {
    const x = sign * (logLength / 2 + 0.006 * radialScale);
    const end = mesh(geo(new THREE.CylinderGeometry(0.437 * radialScale, 0.437 * radialScale, 0.014 * radialScale, 14)), wood, x, logY, 0);
    end.rotation.z = Math.PI / 2;
    const positions = [], indices = [];
    for (let r = 0; r < 6; r++) {
      const radius = 0.048 + r * 0.064;
      const offset = positions.length / 3;
      for (let j = 0; j < 32; j++) {
        const a = j / 32 * Math.PI * 2;
        const wobble = 1 + 0.055 * Math.sin(a * 3 + r * 0.36) + 0.025 * Math.cos(a * 5);
        for (const edge of [-1, 1]) {
          const rr = (radius * wobble + edge * (0.003 + r * 0.0005)) * radialScale;
          positions.push(x + sign * 0.009 * radialScale, logY + 0.016 * radialScale + Math.cos(a) * rr, -0.016 * radialScale + Math.sin(a) * rr);
        }
      }
      for (let j = 0; j < 32; j++) {
        const a = offset + j * 2, b = offset + ((j + 1) % 32) * 2;
        indices.push(a, b, a + 1, b, b + 1, a + 1);
      }
    }
    const bands = geo(new THREE.BufferGeometry());
    bands.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    bands.setIndex(indices);
    bands.computeVertexNormals();
    mesh(bands, ringMat);
    for (let i = 0; i < 3; i++) {
      const a = 0.7 + i * 2.1 + random() * 0.3;
      const crack = mesh(geo(new THREE.BoxGeometry(0.003 * radialScale, 0.12 * radialScale, 0.008 * radialScale)), bark[0], x + sign * 0.011 * radialScale, logY + Math.cos(a) * 0.365 * radialScale, Math.sin(a) * 0.365 * radialScale);
      crack.rotation.x = a;
    }
  }

  if (mossCount > 0) {
    const mossGeo = geo(new THREE.IcosahedronGeometry(1, 1));
    const moss = new THREE.InstancedMesh(mossGeo, mossMat, mossCount);
    instances.push(moss);
    const dummy = new THREE.Object3D();
    const columns = Math.ceil(mossCount / 3);
    const rows = Math.ceil(mossCount / columns);
    for (let i = 0; i < mossCount; i++) {
      const column = i % columns;
      const x = ((columns > 1 ? -1.4 + column * 2.7 / (columns - 1) : -0.05) + (random() - 0.5) * 0.09) * lengthScale;
      const angle = (Math.floor(i / columns) - (rows - 1) / 2) * 0.43 + (random() - 0.5) * 0.18;
      dummy.position.set(x, logY + Math.cos(angle) * 0.486 * radialScale, Math.sin(angle) * 0.486 * radialScale);
      dummy.rotation.set(angle, random() * 0.3, 0);
      dummy.scale.set((0.21 + random() * 0.08) * lengthScale, (0.075 + random() * 0.035) * radialScale, (0.17 + random() * 0.035) * radialScale);
      dummy.updateMatrix();
      moss.setMatrixAt(i, dummy.matrix);
      moss.setColorAt(i, new THREE.Color().setHSL(0.22 + random() * 0.045, 0.39, 0.25 + random() * 0.12));
    }
    moss.castShadow = true;
    moss.receiveShadow = true;
    moss.instanceMatrix.needsUpdate = true;
    if (moss.instanceColor) moss.instanceColor.needsUpdate = true;
    group.add(moss);
  }

  const matureTemplates = [
    [-1.02, 0.01, 0.53, 0.36, -0.10],
    [-0.45, -0.12, 0.91, 0.49, -0.07],
    [0.22, 0.02, 1.13, 0.59, 0.09],
    [0.91, -0.09, 0.70, 0.43, 0.08],
    [0.55, 0.32, 0.43, 0.34, -0.07]
  ];
  const youngTemplates = [
    [-0.82, 0.30, 0.25, 0.18, -0.04],
    [-0.48, 0.34, 0.32, 0.21, 0.02],
    [1.19, 0.19, 0.27, 0.19, 0.025]
  ];
  const mushrooms = [];
  function populate(templates, count, young) {
    for (let i = 0; i < count; i++) {
      let values;
      if (i < templates.length) {
        values = templates[i].slice();
      } else {
        values = [
          -1.25 + random() * 2.5,
          -0.30 + random() * 0.60,
          young ? 0.22 + random() * 0.14 : 0.48 + random() * 0.67,
          young ? 0.16 + random() * 0.07 : 0.32 + random() * 0.25,
          (random() - 0.5) * (young ? 0.08 : 0.2)
        ];
      }
      mushrooms.push({ values, young });
    }
  }
  populate(matureTemplates, matureCount, false);
  populate(youngTemplates, youngCount, true);
  mushrooms.forEach(({ values, young }) => {
    const x = values[0] * lengthScale;
    const z = values[1] * radialScale;
    const height = values[2] * stemHeight;
    const radius = values[3] * capSize;
    const lean = values[4] * stemHeight;
    const baseY = logY + Math.sqrt(Math.max(0, logRadius * logRadius - z * z)) - 0.015 * radialScale;
    const stemRadius = radius * 0.19;
    const stemGeo = geo(new THREE.CylinderGeometry(stemRadius * 0.78, stemRadius * 1.18, height, 8, 4));
    stemGeo.translate(0, height / 2, 0);
    const p = stemGeo.attributes.position;
    for (let i = 0; i < p.count; i++) {
      const t = p.getY(i) / height;
      p.setX(i, p.getX(i) + lean * t * t);
    }
    stemGeo.computeVertexNormals();
    mesh(stemGeo, stemMat, x, baseY, z);
    const dome = radius * (young ? 0.87 : 0.57);
    const profile = [
      new THREE.Vector2(0, 0.008 * capSize),
      new THREE.Vector2(radius * 0.27, -radius * 0.025),
      new THREE.Vector2(radius * 0.70, -radius * 0.018),
      new THREE.Vector2(radius * 0.96, radius * 0.035),
      new THREE.Vector2(radius, radius * 0.11),
      new THREE.Vector2(radius * 0.94, dome * 0.48),
      new THREE.Vector2(radius * 0.74, dome * 0.81),
      new THREE.Vector2(radius * 0.42, dome * 0.97),
      new THREE.Vector2(0, dome)
    ];
    const capGeo = geo(new THREE.LatheGeometry(profile, 14));
    capGeo.clearGroups();
    for (let s = 0; s < 14; s++) {
      for (let j = 0; j < profile.length - 1; j++) {
        capGeo.addGroup((s * (profile.length - 1) + j) * 6, 6, j < 3 ? 1 : 0);
      }
    }
    const colors = [], cp = capGeo.attributes.position;
    const tint = 0.89 + random() * 0.19;
    for (let i = 0; i < cp.count; i++) {
      const y = cp.getY(i);
      const value = tint * (0.91 + 0.14 * y / dome + random() * 0.055);
      colors.push(value, value, value);
    }
    capGeo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    const cap = mesh(capGeo, [capMat, cream], x + lean, baseY + height - 0.014 * capSize, z);
    cap.rotation.z = -lean * 0.6;
  });

  if (branchEnabled) {
    const branch = mesh(geo(new THREE.CylinderGeometry(0.085 * radialScale, 0.16 * radialScale, 0.48 * radialScale, 7)), bark[1], -1.05 * lengthScale, 0.69 * radialScale, -0.43 * radialScale);
    branch.rotation.x = -0.92;
    const tip = new THREE.Vector3(0, 0.245 * radialScale, 0).applyEuler(branch.rotation).add(branch.position);
    const brokenEnd = mesh(geo(new THREE.CylinderGeometry(0.074 * radialScale, 0.074 * radialScale, 0.009 * radialScale, 7)), wood, tip.x, tip.y, tip.z);
    brokenEnd.rotation.copy(branch.rotation);
  }

  group.updateMatrixWorld(true);
  const bounds = new THREE.Box3().setFromObject(group);
  const center = bounds.getCenter(new THREE.Vector3());
  group.children.forEach(child => {
    child.position.x -= center.x;
    child.position.y -= bounds.min.y;
    child.position.z -= center.z;
  });
  if (Number.isFinite(Number(scale)) && Number(scale) > 0) group.scale.setScalar(Number(scale));
  group.updateMatrixWorld(true);
  return {
    root: group,
    dispose: () => {
      instances.forEach(object => object.dispose());
      geometries.forEach(g => g.dispose());
      materials.forEach(m => m.dispose());
    }
  };
}
